def point_type(name, fields, srid_map):
    class Point:
        def __init__(self, *args, **kwargs):
            for field, value in zip(fields, args):
                setattr(self, field, value)
            for field, value in kwargs.items():
                setattr(self, field, value)
        def __repr__(self):
            field_values = []
            for field in fields:
                field_values.append(f"{field}={getattr(self, field)}")
            return f"{name}({', '.join(field_values)})"
        def to_geojson(self, srid):
            if srid in srid_map:
                geojson = {
                    "type": "Point",
                    "coordinates": [getattr(self, field) for field in fields]
                }
                return geojson
            else:
                raise ValueError("Invalid SRID")
