def parse_subparser_arguments(unparsed_arguments, subparsers):
    parser = argparse.ArgumentParser()
    subparsers_dict = {}
    for subparser_name, subparser in subparsers.items():
        subparser_dict = {}
        for action in subparser._actions:
            subparser_dict[action.dest] = action
            parser._add_action(action)
        subparsers_dict[subparser_name] = subparser_dict
    parsed_args, remaining_args = parser.parse_known_args(unparsed_arguments)
    subparser_args = {}
    for subparser_name, subparser_dict in subparsers_dict.items():
        subparser = subparsers[subparser_name]
        subparser_args[subparser_name] = argparse.Namespace()
        for arg_name, action in subparser_dict.items():
            if getattr(parsed_args, arg_name) is not None:
                setattr(subparser_args[subparser_name], arg_name, getattr(parsed_args, arg_name))
