def parse_subparser_arguments(unparsed_arguments, subparsers):
    parser = argparse.ArgumentParser()
    subparser_parsers = {}
    subparser_names = subparsers.keys()
    for name in subparser_names:
        subparser_parsers[name] = subparsers[name].add_parser(name, parents=[parser])
    parsed_arguments = {}
    remaining_arguments = []
    for arg in unparsed_arguments:
        for name in subparser_names:
            try:
                parsed_arguments[name] = subparser_parsers[name].parse_args([arg])
                break
            except argparse.ArgumentError:
                continue
        else:
            remaining_arguments.append(arg)
