def parse_subparser_arguments(unparsed_arguments, subparsers):
    parser = argparse.ArgumentParser()
    subparsers_dict = {}
    for name, subparser in subparsers.items():
        subparsers_dict[name] = parser.add_subparsers(dest=name)
        subparser.add_arguments(subparsers_dict[name])
    parsed_arguments = {}
    remaining_arguments = []
    for argument in unparsed_arguments:
        subparser_found = False
        for name, subparser in subparsers_dict.items():
            try:
                parsed_arguments[name] = subparser.parse_args([argument])
                subparser_found = True
                break
            except argparse.ArgumentError:
                pass
        if not subparser_found:
            remaining_arguments.append(argument)
