    for subparser_name, subparser in subparsers.items():
        subparsers_dict[subparser_name] = parser.add_subparsers(dest=subparser_name)
        subparser.add_arguments(subparsers_dict[subparser_name])
    parsed_args = {subparser_name: None for subparser_name in subparsers}
    remaining_arguments = []
    i = 0
    while i < len(unparsed_arguments):
        arg = unparsed_arguments[i]
        subparser_found = False
        for subparser_name, subparser in subparsers_dict.items():
            try:
                parsed_args[subparser_name] = subparser.parse_args(unparsed_arguments[i:])
                subparser_found = True
                break
            except argparse.ArgumentError:
                pass
        if not subparser_found:
            remaining_arguments.append(arg)
        else:
            i += len(parsed_args[subparser_name]._get_args())
        i += 1
